const httpItem = $input.first();
const firebaseResponse = (httpItem && httpItem.json) ? httpItem.json : {};

const ctx = $('Edit Fields').item.json;
const userMessage = ctx.message || '';
const userId = ctx.userId;
const userName = ctx.userName;
const idToken = ctx.idToken;
const wantsLast = /\b(últim|ultim)\b/i.test(userMessage);

const base = {
  message: userMessage,
  userId,
  userName,
  transactionsFormatted: '',
  transactionCount: 0,
  lastTransaction: '',
  wantsLast,
  wantsMonth: false,
  monthLabel: '',
  monthTransactionsFormatted: '',
  monthTotals: { receita: 0, despesa: 0, saldo: 0, count: 0 },
  monthSummary: 'Ainda não encontrei transações.',
};

const fail = (summary) => [{ json: { ...base, monthSummary: summary } }];

// Valida se o token pertence ao mesmo usuário
const decodeUid = (token) => {
  if (!token) return null;
  const parts = token.split('.');
  if (parts.length < 2) return null;
  const normalized = parts[1].replace(/-/g, '+').replace(/_/g, '/');
  const padded = normalized + '==='.slice((normalized.length + 3) % 4);
  try {
    const payload = JSON.parse(Buffer.from(padded, 'base64').toString('utf8'));
    return payload.user_id || payload.sub || null;
  } catch {
    return null;
  }
};

if (!idToken) {
  return fail('Não consegui validar sua sessão. Faça login novamente para conversar comigo.');
}

const tokenUid = decodeUid(idToken);
if (tokenUid && userId && tokenUid !== userId) {
  return fail('Detectei um usuário diferente do token enviado. Faça login novamente para sincronizar as transações.');
}

if (firebaseResponse && firebaseResponse.error) {
  const status = firebaseResponse.error.status || 0;
  if (status === 401 || status === 403) {
    return fail('Não consegui acessar suas transações porque sua sessão expirou. Entre novamente no app e tente outra vez.');
  }
  return fail(`Não consegui acessar suas transações (erro: ${firebaseResponse.error.message || 'desconhecido'}).`);
}

let documents = [];
if (Array.isArray(firebaseResponse)) {
  // Suporte a :runQuery (cada item pode ter .document)
  documents = firebaseResponse.map(e => e.document).filter(Boolean);
} else if (firebaseResponse.documents) {
  documents = firebaseResponse.documents;
}

// Helpers para ler tipos do Firestore
const getStr = (f, k) => f[k]?.stringValue;
const getBool = (f, k) => f[k]?.booleanValue;
const getNum = (f, k) => {
  const v = f[k];
  if (!v) return null;
  if (v.doubleValue !== undefined) return Number(v.doubleValue);
  if (v.integerValue !== undefined) return Number(v.integerValue);
  if (v.stringValue !== undefined && v.stringValue !== '') {
    const n = Number(v.stringValue);
    return Number.isFinite(n) ? n : null;
  }
  return null;
};

const parseDate = (f) => {
  // Suporta DataMovimentacao (MAIÚSCULA) e fallback para dataMovimentacao (minúscula)
  const intRaw = f.DataMovimentacao?.integerValue ?? f.dataMovimentacao?.integerValue;
  const tsVal = f.DataMovimentacao?.timestampValue ?? f.dataMovimentacao?.timestampValue;
  const strRaw = f.DataMovimentacao?.stringValue ?? f.dataMovimentacao?.stringValue;

  if (intRaw !== undefined && intRaw !== null) {
    const ms = Number(intRaw);
    if (Number.isFinite(ms)) return new Date(ms);
  }
  if (tsVal) {
    const d = new Date(tsVal);
    if (!isNaN(d.getTime())) return d;
  }
  if (strRaw) {
    const n = Number(strRaw);
    if (Number.isFinite(n)) {
      const d = new Date(n);
      if (!isNaN(d.getTime())) return d;
    }
    const d = new Date(strRaw);
    if (!isNaN(d.getTime())) return d;
  }
  return null;
};

const items = (documents || []).map(doc => {
  const f = doc.fields || {};
  const dt = parseDate(f);
  const dataPt = dt ? dt.toLocaleDateString('pt-BR') : 'Data não informada';
  const valorNum = getNum(f, 'Valor') ?? getNum(f, 'valor') ?? 0;
  const isSaida = (getBool(f, 'IsSaida') ?? getBool(f, 'isSaida') ?? false) === true;
  const tipo = isSaida ? 'Despesa' : 'Receita';
  let nome = getStr(f, 'Nome') || getStr(f, 'nome') || 'Sem nome';
  const desc = getStr(f, 'Descricao') || getStr(f, 'descricao');
  if (desc && desc.trim() !== '') nome += ` (${desc})`;
  return { dt, data: dataPt, nome, valor: valorNum, tipo };
}).filter(i => i.dt instanceof Date && !isNaN(i.dt.getTime()))
  .sort((a,b) => b.dt - a.dt);

const transactionsFormatted = items.length
  ? items.map(i => {
      const valor = i.valor.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });
      const emoji = i.tipo === 'Despesa' ? '🔴' : '🟢';
      return `• [${i.data}] ${emoji} ${i.nome} - ${valor} (${i.tipo})`;
    }).join('\n')
  : 'Ainda não encontrei transações registradas.';

let lastTransaction = '';
if (items.length) {
  const i = items[0];
  const valor = i.valor.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });
  const emoji = i.tipo === 'Despesa' ? '🔴' : '🟢';
  lastTransaction = `[${i.data}] ${emoji} ${i.nome} - ${valor} (${i.tipo})`;
}

// Detecta mês/ano no texto (pt-BR)
const monthMap = {
  'janeiro': 0, 'fevereiro': 1, 'março': 2, 'marco': 2, 'abril': 3, 'maio': 4, 'junho': 5,
  'julho': 6, 'agosto': 7, 'setembro': 8, 'outubro': 9, 'novembro': 10, 'dezembro': 11
};
const lower = userMessage.toLowerCase();
let monthIdx = null;
for (const [k, v] of Object.entries(monthMap)) { if (lower.includes(k)) { monthIdx = v; break; } }

let year = null;
const yearMatch = lower.match(/\b(20\d{2})\b/);
if (yearMatch) { year = parseInt(yearMatch[1], 10); }
if (!year && /(esse|deste|desse|este) ano/.test(lower)) { year = new Date().getFullYear(); }

const wantsMonth = monthIdx !== null && (year !== null || /(esse|deste|desse|este) ano/.test(lower));
if (monthIdx !== null && year === null) { year = new Date().getFullYear(); }

let monthItems = [];
let monthTransactionsFormatted = '';
let monthTotals = { receita: 0, despesa: 0, saldo: 0, count: 0 };
let monthLabel = '';
let monthSummary = base.monthSummary;

if (wantsMonth && year !== null) {
  monthItems = items.filter(i => i.dt.getMonth() === monthIdx && i.dt.getFullYear() === year);
  monthTransactionsFormatted = monthItems.map(i => {
    const valor = i.valor.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });
    const emoji = i.tipo === 'Despesa' ? '🔴' : '🟢';
    return `• [${i.data}] ${emoji} ${i.nome} - ${valor} (${i.tipo})`;
  }).join('\n');

  for (const m of monthItems) {
    if (m.tipo === 'Despesa') monthTotals.despesa += m.valor; else monthTotals.receita += m.valor;
  }
  monthTotals.saldo = monthTotals.receita - monthTotals.despesa;
  monthTotals.count = monthItems.length;

  const monthNames = ['Janeiro','Fevereiro','Março','Abril','Maio','Junho','Julho','Agosto','Setembro','Outubro','Novembro','Dezembro'];
  monthLabel = `${monthNames[monthIdx]}/${year}`;

  if (monthTotals.count > 0) {
    const r = monthTotals.receita.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });
    const d = monthTotals.despesa.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });
    const s = monthTotals.saldo.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });
    monthSummary = `Resumo de ${monthLabel}:\nTransações: ${monthTotals.count}\nReceitas: ${r}\nDespesas: ${d}\nSaldo: ${s}`;
    if (monthTransactionsFormatted) { monthSummary += `\n\n${monthTransactionsFormatted}`; }
  } else {
    monthSummary = `Não encontrei transações para ${monthLabel}.`;
  }
}

return [{ json: {
  ...base,
  transactionsFormatted,
  transactionCount: items.length,
  lastTransaction,
  wantsMonth,
  monthLabel,
  monthTransactionsFormatted,
  monthTotals,
  monthSummary,
}}];

parameters.text:
=Pergunta: {{ $json.message }}

Dados do usuário disponíveis:
- UserID: {{ $json.userId }}
- Transações: {{ $json.transactionsFormatted }}
- Nome do usuario: {{ $json.userName }}

Responda à pergunta usando os dados de transações fornecidos acima.
Pode responder com emojis
PS: Há transações recorrentes. Ao lidar com datas, verifique se não são recorrentes. Ex: ao pedir “última transação”, considerar apenas até a data atual (ex.: 08/10/2025), não futuras. Se pedir “transações do mês”, inclua também as recorrentes.
